#!/usr/bin/env python3
from __future__ import annotations
import argparse,json
from pathlib import Path
class ReportError(RuntimeError):pass
def load(path:Path):
 try:return json.loads(path.read_text(encoding="utf-8"))
 except (OSError,json.JSONDecodeError) as exc:raise ReportError(f"cannot load {path}: {exc}") from exc
def render(scores_path:Path,prices_path:Path,history_path:Path,output_dir:Path)->tuple[Path,Path]:
 scores=load(scores_path);prices=load(prices_path);history=load(history_path);dates={x.get("trade_date") for x in (scores,prices,history)}
 if len(dates)!=1:raise ReportError(f"input dates differ: {dates}")
 day=next(iter(dates));echarts_path=Path(__file__).resolve().parent.parent/"assets"/"echarts.min.js"
 try:echarts_js=echarts_path.read_text(encoding="utf-8").replace("</script","<\\/script")
 except OSError as exc:raise ReportError(f"cannot load {echarts_path}: {exc}") from exc
 bundle={"scores":scores,"prices":prices,"history":history};payload=json.dumps(bundle,ensure_ascii=False,separators=(",",":")).replace("</","<\\/")
 template=r"""<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>台股每日投本比報告 __DAY__</title><script>__ECHARTS__</script><style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#0b1220;color:#e5e7eb;font-family:system-ui,sans-serif}main{max-width:1500px;margin:auto;padding:18px}.notice{padding:12px;margin:12px 0;border:1px solid #f59e0b;background:#422006;border-radius:9px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px}.card{background:#111827;padding:13px;border-radius:9px}.filters{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0}input,select,button{padding:8px;background:#1f2937;color:#fff;border:1px solid #64748b;border-radius:6px}.wrap{overflow:auto;background:#111827}table{border-collapse:collapse;width:100%;min-width:1120px}th,td{padding:6px 5px;font-size:13px;border-bottom:1px solid #334155;text-align:right;white-space:nowrap}th:nth-child(2),td:nth-child(2),th:nth-child(3),td:nth-child(3){text-align:left}th{background:#172033;position:sticky;top:0}.red{color:#fb7185}.green{color:#4ade80}.orange{color:#f59e0b}.chart{width:100%;height:min(720px,75vh);min-height:480px;background:#111827}.chart-modal-card{width:min(1200px,96vw);max-width:1200px}details{min-width:280px;max-width:420px;text-align:left;white-space:normal}.reason-section{padding:7px 0;border-bottom:1px solid #334155}.reason-section:last-child{border-bottom:0}.reason-section b{color:#f8fafc}.reason-section ul{margin:5px 0 0;padding-left:20px}.reason-section li{margin:3px 0;color:#cbd5e1}.foot{margin-top:16px;padding:12px;border:1px solid #64748b}.help-button{margin:12px 0;background:#1d4ed8}.modal{display:none;position:fixed;inset:0;z-index:9999;background:rgba(2,6,23,.82);padding:16px}.modal.open{display:flex;align-items:center;justify-content:center}.modal-card{width:min(760px,100%);max-height:90vh;overflow:auto;background:#111827;border:1px solid #64748b;border-radius:12px;padding:18px;text-align:left}.modal-head{display:flex;justify-content:space-between;gap:12px;align-items:center;position:sticky;top:-18px;background:#111827;padding:10px 0}.modal-card h2,.modal-card h3{color:#f8fafc}.modal-card li{margin:6px 0;color:#cbd5e1}.modal-card code{white-space:normal;color:#fbbf24}</style></head><body><main><h1>台股每日投信投本比與技術報告</h1><div class="foot">本報告僅供量化篩選、資訊整理與研究用途，不構成投資建議、買賣邀約或報酬保證。使用者應自行確認資料並承擔風險。</div><div class="notice">期間累計買超比例為估算，不是投信實際持股比例。線圖函式庫已內嵌，可離線顯示。<div id="warnings"></div></div><button type="button" id="showMethod" class="help-button">查看篩選機制</button><div id="methodModal" class="modal" role="dialog" aria-modal="true" aria-labelledby="methodTitle"><section class="modal-card"><div class="modal-head"><h2 id="methodTitle">篩選與評分機制</h2><button type="button" id="closeMethod">關閉</button></div><h3>一、全市場初篩</h3><ol><li>僅保留上市、上櫃普通股，排除ETF、ETN、權證、特別股及資料不完整商品。</li><li>當日投信必須淨買超。</li><li>投本比至少0.4%，或進入全市場正投本比前30名。</li><li>成交量至少3,000張，實收資本額低於50億元。</li><li>激進模式要求投信至少連買1日；穩健模式至少連買3日。</li><li>交易、流動性與資料日期必須通過驗證；缺值不視為通過。</li></ol><p><code>投本比＝當日投信淨買超股數 ÷ 發行股數 × 100</code></p><h3>二、100分評分</h3><ul><li><b>投本比強度 25分：</b>依絕對投本比及全市場排名評分。</li><li><b>投信持續性 20分：</b>依連買日數、近3日買超日數及買盤是否加速評分。</li><li><b>累計籌碼 15分：</b>3%～7%最佳；使用估算值時最高限制為11分。</li><li><b>外資同步 10分：</b>當日同步+4、近3日外資累計買超+3、近3日皆同步+3。</li><li><b>均線結構 15分：</b>MA5＞MA10＞MA20、均線向上及收盤站上均線加分。</li><li><b>突破量價 15分：</b>突破20日高點、接近高點、收紅K及合理放量加分；長上影、高開走低與假突破扣分。</li></ul><h3>三、評級</h3><ul><li>80～100：強勢候選</li><li>70～79：可觀察</li><li>60～69：條件不足</li><li>低於60：不列入</li></ul><p>初篩候選不等於最終推薦。技術資料缺失時，技術分為0、信心度降為低，且不產生交易計畫。</p></section></div><div id="reasonModal" class="modal" role="dialog" aria-modal="true" aria-labelledby="reasonTitle"><section class="modal-card"><div class="modal-head"><h2 id="reasonTitle">分項原因</h2><button type="button" id="closeReason">關閉</button></div><div id="reasonContent"></div></section></div><div class="cards"><div class="card">交易日<br><b>__DAY__</b></div><div class="card">候選<br><b id="candidateCount"></b></div><div class="card">強勢候選<br><b id="strongCount"></b></div><div class="card">可觀察<br><b id="watchCount"></b></div></div><div class="filters"><input id="q" placeholder="代號或名稱"><input id="min" type="number" value="0" min="0" max="100" placeholder="最低分"><select id="mode"><option value="">全部模式</option><option value="conservative">穩健</option><option value="aggressive">激進</option></select><select id="rating"><option value="">全部評級</option><option>強勢候選</option><option>可觀察</option><option>條件不足</option><option>不列入</option></select><select id="sync"><option value="">全部法人</option><option value="today">當日同買</option><option value="both">當日及近3日同買</option></select><button type="button" id="applyFilters">篩選</button></div><div class="wrap"><table><thead><tr><th>#</th><th>代號</th><th>名稱</th><th>分數</th><th>評級</th><th>模式</th><th>投本比%</th><th>全市場排名</th><th>連買日</th><th>近3日投信張</th><th>當日外資張</th><th>近3日外資張</th><th>法人同步</th><th>量張</th><th>資本額億</th><th>分項原因</th><th>線圖</th></tr></thead><tbody id="rows"></tbody></table></div><div id="chartModal" class="modal" role="dialog" aria-modal="true" aria-labelledby="chartTitle"><section class="modal-card chart-modal-card"><div class="modal-head"><h2 id="chartTitle">技術線圖</h2><button type="button" id="closeChart">關閉</button></div><div id="chartCanvas" class="chart"></div></section></div><div class="foot">本報告僅供量化研究，不構成投資建議。歷史行情、法人籌碼及技術訊號不保證未來結果。</div></main><script>const D=__DATA__;const S=D.scores.records;const P=new Map(D.prices.records.map(x=>[x.stock_code,x]));const H=new Map(D.history.records.map(x=>[x.stock_code,x]));const reasonHtml=new Map();const latestInst=code=>(H.get(code)?.sitc_history||[]).find(x=>x.trade_date===D.scores.trade_date)||{};const esc=x=>String(x??"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;"}[c]));const fmt=(x,n=2)=>Number(x).toLocaleString("zh-TW",{maximumFractionDigits:n});const prettyReason=s=>String(s).replace(/(-?\d+\.\d{4})\d+/g,m=>Number(m).toFixed(4));const sectionNames={investment_ratio:"投本比強度",sitc_continuity:"投信買盤持續性",chip_position:"累計籌碼狀態",foreign_sync:"外資同步",moving_averages:"均線結構",breakout_volume:"突破與量價"};document.querySelector("#candidateCount").textContent=S.length;document.querySelector("#strongCount").textContent=D.scores.counts.strong;document.querySelector("#watchCount").textContent=D.scores.counts.watch;document.querySelector("#warnings").innerHTML=(D.scores.warnings||[]).map(x=>"<div>⚠ "+esc(x)+"</div>").join("");const methodModal=document.querySelector("#methodModal"),closeMethod=()=>methodModal.classList.remove("open");document.querySelector("#showMethod").addEventListener("click",()=>methodModal.classList.add("open"));document.querySelector("#closeMethod").addEventListener("click",closeMethod);methodModal.addEventListener("click",event=>{if(event.target===methodModal)closeMethod()});document.addEventListener("keydown",event=>{if(event.key==="Escape")closeMethod()});const reasonModal=document.querySelector("#reasonModal"),closeReason=()=>reasonModal.classList.remove("open");document.querySelector("#closeReason").addEventListener("click",closeReason);reasonModal.addEventListener("click",event=>{if(event.target===reasonModal)closeReason()});document.addEventListener("keydown",event=>{if(event.key==="Escape")closeReason()});let chartInstance=null;const chartModal=document.querySelector("#chartModal"),chartCanvas=document.querySelector("#chartCanvas"),closeChart=()=>{if(chartInstance){chartInstance.dispose();chartInstance=null}chartCanvas.innerHTML="";chartModal.classList.remove("open")};document.querySelector("#closeChart").addEventListener("click",closeChart);chartModal.addEventListener("click",event=>{if(event.target===chartModal)closeChart()});document.addEventListener("keydown",event=>{if(event.key==="Escape")closeChart()});window.addEventListener("resize",()=>chartInstance?.resize());function drawTable(){const q=document.querySelector("#q").value.trim().toLowerCase(),min=Number(document.querySelector("#min").value||0),mode=document.querySelector("#mode").value,rating=document.querySelector("#rating").value,sync=document.querySelector("#sync").value;const list=S.filter(x=>{const z=latestInst(x.stock_code),today=(z.sitc_net_shares||0)>0&&(z.foreign_net_shares||0)>0,both=today&&x.foreign_net_shares_3d_sum>0;return (!q||(x.stock_code+x.stock_name).toLowerCase().includes(q))&&x.total_score>=min&&(!rating||x.rating===rating)&&(!mode||(mode==="conservative"?x.conservative_passed:x.aggressive_passed))&&(!sync||(sync==="today"?today:both))});reasonHtml.clear();document.querySelector("#rows").innerHTML=list.map((x,i)=>{const modes=x.conservative_passed?"穩健、激進":"激進",z=latestInst(x.stock_code),todaySync=(z.sitc_net_shares||0)>0&&(z.foreign_net_shares||0)>0,threeSync=x.sitc_net_shares_3d_sum>0&&x.foreign_net_shares_3d_sum>0,syncLabel=todaySync&&threeSync?"當日＋3日":todaySync?"當日同買":threeSync?"3日同買":"分歧",sections=Object.entries(x.sections).map(([k,v])=>"<div class=\"reason-section\"><b>"+esc(sectionNames[k]||k)+" "+v.score+"/"+v.max+"</b><ul>"+v.reasons.map(r=>"<li>"+esc(prettyReason(r))+"</li>").join("")+"</ul></div>").join("");reasonHtml.set(x.stock_code,sections);return "<tr><td>"+(i+1)+"</td><td>"+esc(x.stock_code)+"</td><td>"+esc(x.stock_name)+"</td><td><b>"+x.total_score+"</b></td><td>"+esc(x.rating)+"</td><td>"+modes+"</td><td>"+fmt(x.investment_ratio_pct,4)+"</td><td>"+x.positive_ratio_rank+"</td><td>"+x.sitc_buy_streak+"</td><td class=\""+(x.sitc_net_shares_3d_sum>=0?"red":"green")+"\">"+fmt(x.sitc_net_shares_3d_sum/1000)+"</td><td class=\""+(Number(z.foreign_net_shares||0)>=0?"red":"green")+"\">"+fmt(Number(z.foreign_net_shares||0)/1000)+"</td><td class=\""+(x.foreign_net_shares_3d_sum>=0?"red":"green")+"\">"+fmt(x.foreign_net_shares_3d_sum/1000)+"</td><td>"+esc(syncLabel)+"</td><td>"+fmt(x.volume_lots)+"</td><td>"+fmt(x.paid_in_capital_twd/1e8)+"</td><td><button type=\"button\" class=\"reason-toggle\" data-code=\""+esc(x.stock_code)+"\">查看</button></td><td>"+(P.has(x.stock_code)?"<button type=\"button\" class=\"chart-toggle\" data-code=\""+esc(x.stock_code)+"\">展開</button>":"<span class=\"orange\">無技術圖</span>")+"</td></tr>"}).join("")}drawTable();document.querySelector("#applyFilters").addEventListener("click",drawTable);document.querySelector("tbody").addEventListener("click",event=>{const reasonButton=event.target.closest(".reason-toggle");if(reasonButton){const code=reasonButton.dataset.code,stock=S.find(x=>x.stock_code===code);document.querySelector("#reasonTitle").textContent=code+" "+(stock?.stock_name||"")+"－分項原因";document.querySelector("#reasonContent").innerHTML=reasonHtml.get(code)||"無資料";reasonModal.classList.add("open");return}const chartButton=event.target.closest(".chart-toggle");if(chartButton)toggleChart(chartButton.dataset.code)});function sma(a,n){return a.map((_,i)=>i<n-1?null:a.slice(i-n+1,i+1).reduce((s,v)=>s+v,0)/n)}function toggleChart(code){const item=P.get(code),hist=H.get(code);if(chartInstance){chartInstance.dispose();chartInstance=null}chartCanvas.innerHTML="";document.querySelector("#chartTitle").textContent=code+" "+(item?.stock_name||"")+"－技術線圖";chartModal.classList.add("open");if(typeof echarts==="undefined"){chartCanvas.textContent="線圖函式庫載入失敗";return}if(!item||!hist){chartCanvas.textContent="技術或法人歷史資料缺失";return}const p=item.ohlcv_history,h=hist.sitc_history,hm=new Map(h.map(x=>[x.trade_date,x])),dates=p.map(x=>x.trade_date),close=p.map(x=>+x.close),k=p.map(x=>[+x.open,+x.close,+x.low,+x.high]),vol=p.map(x=>x.volume_shares/1000),sitc=dates.map(d=>(hm.get(d)?.sitc_net_shares??null)/1000),foreign=dates.map(d=>(hm.get(d)?.foreign_net_shares??null)/1000),chartInstance=echarts.init(chartCanvas);const chart=chartInstance;chart.setOption({animation:false,title:{text:code+" "+item.stock_name,textStyle:{color:"#fff"}},legend:{data:["K線","MA5","MA10","MA20","成交量","投信","外資"],textStyle:{color:"#ddd"}},tooltip:{trigger:"axis",axisPointer:{type:"cross"}},axisPointer:{link:[{xAxisIndex:"all"}]},grid:[{left:60,right:30,top:55,height:"48%"},{left:60,right:30,top:"60%",height:"14%"},{left:60,right:30,top:"79%",height:"15%"}],xAxis:[{type:"category",data:dates,axisLabel:{show:false}},{type:"category",gridIndex:1,data:dates,axisLabel:{show:false}},{type:"category",gridIndex:2,data:dates}],yAxis:[{scale:true},{scale:true,gridIndex:1,name:"張"},{scale:true,gridIndex:2,name:"張"}],dataZoom:[{type:"inside",xAxisIndex:[0,1,2],start:45,end:100},{type:"slider",xAxisIndex:[0,1,2],bottom:5,start:45,end:100}],series:[{name:"K線",type:"candlestick",data:k,itemStyle:{color:"#ef4444",color0:"#22c55e",borderColor:"#ef4444",borderColor0:"#22c55e"}},{name:"MA5",type:"line",data:sma(close,5),showSymbol:false},{name:"MA10",type:"line",data:sma(close,10),showSymbol:false},{name:"MA20",type:"line",data:sma(close,20),showSymbol:false},{name:"成交量",type:"bar",xAxisIndex:1,yAxisIndex:1,data:vol},{name:"投信",type:"bar",xAxisIndex:2,yAxisIndex:2,data:sitc,itemStyle:{color:p=>p.value>=0?"#ef4444":"#22c55e"}},{name:"外資",type:"bar",xAxisIndex:2,yAxisIndex:2,data:foreign,itemStyle:{color:p=>p.value>=0?"#fb7185":"#4ade80"}}]});requestAnimationFrame(()=>chartInstance?.resize())}</script></body></html>"""
 html=template.replace("__DAY__",day).replace("__DATA__",payload).replace("__ECHARTS__",echarts_js);stamp=day.replace("-","");output_dir.mkdir(parents=True,exist_ok=True);dated=output_dir/f"tw_stock_momentum_report_{stamp}.html";latest=output_dir/"latest.html";dated.write_text(html,encoding="utf-8");latest.write_text(html,encoding="utf-8");data_dir=output_dir/"data";data_dir.mkdir(parents=True,exist_ok=True);(data_dir/f"report_{stamp}.json").write_text(json.dumps(bundle,ensure_ascii=False,indent=2)+"\n",encoding="utf-8");return latest,dated
def main()->int:
 p=argparse.ArgumentParser();p.add_argument("--scores",type=Path,required=True);p.add_argument("--prices",type=Path,required=True);p.add_argument("--history",type=Path,required=True);p.add_argument("--output-dir",type=Path,required=True);a=p.parse_args();latest,dated=render(a.scores,a.prices,a.history,a.output_dir);print(f"wrote {latest} and {dated}");return 0
if __name__=="__main__":
 try:raise SystemExit(main())
 except ReportError as exc:print(f"ERROR: {exc}",file=__import__("sys").stderr);raise SystemExit(2)
